python - <<'PY'
from more_itertools import interleave_evenly, sliced, numeric_range
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta

for inputs in ([], [[]], [[], []], [[], [1, 2], []]):
    expected = [1, 2] if any(inputs) else []
    assert list(interleave_evenly(inputs)) == expected
    assert list(interleave_evenly(inputs, lengths=list(map(len, inputs)))) == expected
for strict in (False, True):
    for seq in ([], [1, 2, 3], 'abc'):
        try:
            sliced(seq, -1, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError('negative slice size accepted')
for start in range(-5, 6):
    for stop in range(-5, 6):
        for step in (-3, -1, 1, 3):
            r = numeric_range(start, stop, step)
            assert list(reversed(r)) == list(range(start, stop, step))[::-1]
for args in ((0., 1., .1), (1., 0., -.1), (0., 0., .1),
             (Decimal('0.1'), Decimal('1'), Decimal('0.1')),
             (Fraction(1, 3), Fraction(2), Fraction(1, 3)),
             (datetime(2020, 1, 1), datetime(2020, 1, 5), timedelta(days=1)),
             (datetime(2020, 1, 1), datetime(2020, 1, 1), timedelta(days=-1))):
    r = numeric_range(*args)
    assert list(reversed(r)) == list(r)[::-1], args
print('Targeted regression checks passed')
PY
